a2a_name = "Au2Analysis.exe" if os.name == "nt" else "Au2Analysis"
_global_a2a_dir = os.path.join(
    os.path.abspath(
        os.path.dirname(
            inspect.getfile(
                inspect.currentframe()))),
    "tool")
_global_a2a_exe_path = os.path.join(_global_a2a_dir, a2a_name)


def check_logs_with_au2anlysis(
        ini_path,
        log_need_to_check,
        ini_modify=None,
        save_log_directory=''):
    """This keyword used for calling Au2Analysis.exe to analysis kinds of logs,
       such as UDP log, Trace log, TM500 log and TtiTrace log.
    log_need_to_check example:
        | u |  UDP log |
        | t |  Trace log |
        | m |  TM500 log |
        | i |  TtiTrace log |
        | p |  TM500 Protocol log, iphy log |
        | w |  Wireshark log |

    Steps:
    | step1 | copy ini, pdm, csv files to target log folder |
    | step2 | modify ini file in target log folder |
    | step3 | run au2analysis.exe and check result |

    Arguments:
    | Input Parameters   | Man. | Description |
    | ini_path           | Yes  | ini file path |
    | log_need_to_check  | Yes  | should be "u t m i p w"  |
    | ini_modify         | No   | default as None, could be string or list |
    | kwargs             | No   | could be "save_log_directory=c:\\A2A\\Logfolder" |

    Example
    | check_logs_with_au2anlysis   |  c:\\A2A\\A2A.ini | tmip | save_log_directory=c:\\A2A\\Logfolder |
    | check_logs_with_au2anlysis   |  c:\\A2A\\A2A.ini |  uw | UDPLOG_TAG_1: UDPlog*.log |  save_log_directory=c:\\A2A\\Logfolder |
    | ${modify_list} | create list | LOGDIR: D:\\A2A | UDPLOG_TAG_1: UDPlog*.log |
    | check_logs_with_au2anlysis   |  c:\\A2A\\A2A.ini | uw | ${modify_list} | save_log_directory=c:\\A2A\\Logfolder |
    """

    target_log_folder = save_log_directory
    if not os.path.exists(target_log_folder):
        os.makedirs(target_log_folder)
    ini_folder, ini_name = os.path.split(ini_path)
    new_ini_path = os.path.join(target_log_folder, ini_name)
    if new_ini_path != ini_path:

        shutil.copy(ini_path, target_log_folder)
        pdm_files = _parse_pdm_file_name(ini_path)

        for pdm_file in pdm_files:
            shutil.copy(os.path.join(ini_folder, pdm_file), target_log_folder)

    _modify_a2a_ini_file(new_ini_path, "LOGDIR:%s" % target_log_folder)

    if ini_modify is not None:
        _modify_a2a_ini_file(new_ini_path, ini_modify)

    _run_a2a_and_check_result(
        new_ini_path,
        target_log_folder,
        log_need_to_check)


def _check_pass_or_fail(ret):
    err_number = 0
    if len(ret) < 10:
        raise Exception(
            "Run failed 'The system cannot find the path specified.'")
    line = ret

    if re.search("(?i).*ERROR:.*", line) \
            or re.search("(?i).*CRITICAL:.*", line) \
            or re.search("(?i).*is not recognized as.*", line) \
            or re.search("(?i).*The system cannot find the path specified.*", line) \
            or re.search("(?i).*could not be found.*", line):
        err_number += 1
    return err_number


def _run_a2a_and_check_result(
        ini_path,
        target_log_folder,
        log_need_to_check=""):

    if log_need_to_check == "":
        raise Exception("ERR/: No log type option.")

    # Get command line option
    option = ' -%s ' % log_need_to_check.replace(' ', '').lower().replace('d', 'D')

    new_ini_file = _a2a_file_variable_replace(ini_path)

    time_stamp = time.strftime(r"%M%S", time.localtime())
    log_path = os.path.join(
        target_log_folder, "%s%s.log" %
        (time_stamp, option.strip()))
    cmd = "%s -c \"%s\" %s -F -L \"%s\"" % \
          (_global_a2a_exe_path, new_ini_file, option, log_path)
    log.info(cmd)
    if os.name != "nt":
        modify_permission = "chmod -R 777 %s/*" % _global_a2a_dir
        log.info(modify_permission)
        os.system(modify_permission)
        log.info('sudo %s' % modify_permission)
        os.system('sudo %s' % modify_permission)
        log.info('cd %s;chmod -R 777 *' % _global_a2a_dir)
        os.system('cd %s;chmod -R 777 *' % _global_a2a_dir)
        log.info(os.popen('ls %s' % _global_a2a_dir).read())
    ret = os.popen(cmd).read()
    log.info(ret)
    err_number = _check_pass_or_fail(ret)
    if (int(err_number) == 0):
        log.info("Check log successfully")
        return True
    else:
        raise Exception(
            "ERR/: Check log failed")


def _args_check(parameters):
    ini_dict = {}
    # check change list format
    if parameters is None:
        log.info("No changes needed!")
        return
    elif isinstance(parameters, six.string_types):
        tmp = parameters.split(":", 1)
        ini_dict[tmp[0]] = parameters
    elif isinstance(parameters, list):
        for content in parameters:
            tmp = content.split(":", 1)
            ini_dict[tmp[0]] = content
    else:
        raise Exception("Please input such as 'LOGDIR: D:\\Au2Analysis'")
    return ini_dict


def _modify_a2a_ini_file(src_file, parameters, dst_file=""):
    """This keyword will modify the Au2Analysis ini file based on the given parameters.

    |  Input Parameters   | Man. | Description |
    |      src_file       | Yes  | Au2Analysis ini file path |
    |     parameters      | Yes  | parameters need to be chaneged, format will be string or list  |
    |      dst_file       |  NO  | default will be same as src_file  |

    Example
    | Modify A2A INI File | "c:\\A2A\\a2a.ini" | ["LOGDIR: D:\\A2A", "UDPLOG_TAG_1: UDPlog*.log"] |
    """
    if not os.path.exists(src_file):
        raise Exception("Can't find '%s', please check!" % src_file)

    ini_dict = _args_check(parameters)
    # read ini file
    lines = filec.read_file(src_file, 'r', "list")

    # modify ini file content
    for key in list(ini_dict.keys()):
        tag_if_changed = False
        for index in range(len(lines)):
            if re.search("^%s:" % (key), lines[index]):
                lines[index] = ini_dict[key] + "\n\n"
                tag_if_changed = True

        pass_info = "Change '%s' success!" % (ini_dict[key])
        fail_info = "change '%s' not found! Bypassed!" % (ini_dict[key])
        log.info(pass_info if tag_if_changed else fail_info)

    # write ini file
    dst_file = dst_file if dst_file else src_file
    filec.write_file(dst_file, lines, 'w')


def _a2a_file_variable_replace(ini_file):
    """This keyword will replace a2a ini or pdm file varible.
        if there are the varialbe type as robot ${xxx}, it will replace it from robot varible.

    |  Input Parameters   | Man. | Description |
    |  ini_file       | Yes  | Au2Analysis ini file path |
    |  return value   |  modified_ini_file_path  |

    Example
    | _a2a_file_variable_replace | "c:\\A2A\\a2a.ini" |
    """
    if not os.path.exists(ini_file):
        raise Exception("Can't find '%s', please check!" % ini_file)
    f_path, _ = os.path.split(ini_file)

    # ini file variable replace
    modify_ini = _template_file_variable_replace(ini_file)

    ini_file_new = os.path.join(f_path, modify_ini)

    # parse pdm file name and variable replace all pdm file
    pmds = _parse_pdm_file_name(ini_file)

    src_pdm = pmds
    tar_pdm = [_template_file_variable_replace(
        os.path.join(
            f_path, pdm)) for pdm in pmds]

    ini_content = filec.read_file(ini_file_new)
    change_flag = False
    for i in range(len(src_pdm)):
        if src_pdm[i] != tar_pdm[i]:
            pattern = re.compile(src_pdm[i])
            ini_content, count = pattern.subn(tar_pdm[i], ini_content)
            log.info("Replace '%s' as '%s' %s times in '%s'" %
                     (src_pdm[i], tar_pdm[i], count, ini_file_new))
            change_flag = True

    if change_flag:
        filec.write_file(ini_file_new, str(ini_content), 'w')
    return ini_file_new


def _template_file_variable_replace(src_file):
    f_path, f_name = os.path.split(src_file)
    tar_f_name = "m_" + f_name
    tar_file = os.path.join(f_path, tar_f_name)

    f_content = filec.read_file(src_file)
    if "${" in f_content:
        f_content = f_content.replace("\\", "\\\\")
        f_content_new = BuiltIn().replace_variables(f_content)
        filec.write_file(tar_file, f_content_new, 'w')
        log.info(
            "Replace variable from '%s' to '%s' OK." %
            (src_file, tar_file))
        return tar_f_name
    else:
        return f_name


def _parse_pdm_file_name(src_file):
    pdm_file_list = []
    with open(src_file, 'r') as f_obj:
        lines = f_obj.readlines()
    for line in lines:
        ret = re.search(r'^PARADIGM\s*[:=]\s*(.*)\s*', line)
        if ret:
            pdm = ret.groups()[0].strip()
            if '\\' in pdm:
                pdm = pdm.split('\\')[-1]
            elif '/' in pdm:
                pdm = pdm.split('/')[-1]
            pdm_file_list.append(pdm)
    return list(set(pdm_file_list))


def _file_variable_replace(src_file):
    f_content = filec.read_file(src_file)
    if "${" in f_content:
        f_content = f_content.replace("\\", "\\\\")
        f_content_new = BuiltIn().replace_variables(f_content)
        filec.write_file(src_file, f_content_new, 'w')


def check_multi_log(ini_path, log_save_path):
    "could check wireshark, tm500 protocol and iphy log"
    ini_folder, ini_name = os.path.split(ini_path)
    new_ini_path = os.path.join(log_save_path, ini_name)

    pdm_files = _parse_pdm_file_name(ini_path)
    if new_ini_path != ini_path:
        shutil.copy(ini_path, log_save_path)
        for pdm_file in pdm_files:
            shutil.copy(os.path.join(ini_folder, pdm_file), log_save_path)
    pdm_files.append(ini_name)
    for f in pdm_files:
        _file_variable_replace(os.path.join(log_save_path, f))
    from msg_check.parse_condition import Condition_Handle
    p = Condition_Handle()
    return p.parse_conditon_file(new_ini_path, log_save_path)


def wireshark_filter_msg(input_file, output_file, filter_msg):
    "doc"
    kilobytes = 1024
    megabytes = kilobytes * 1000
    chunksize = int(20 * megabytes)
    flag = 0
    pre_content = ''
    new_frames = []
    with open(input_file, 'r') as fobj:
        while True:
            chunk = fobj.read(chunksize)
            if len(chunk) < chunksize:
                flag += 1

            chunk = pre_content + chunk
            frames = chunk.split('\n\n')

            check_list = frames if flag == 1 else frames[:-1]
            for frame in check_list:
                if re.search(filter_msg, frame):
                    new_frames.append(frame)
            if flag == 1:
                break
            else:
                pre_content = frames[-1]

    with open(output_file, 'w') as fileobj:
        fileobj.write('\n\n'.join(new_frames))


def exe_subprocess(cmd):
    log.info('\n--> execute "{}"'.format(cmd))

    ret = subprocess.check_output(cmd, shell=True)
    ret = ret.decode()
    log.info('<-- return "{}"'.format(ret))
    return ret
